toolCall.argumentsJson:
{"CommandLine":"$folders = @(
    ".ollama", ".gradle", ".m2", ".minikube", ".cache", ".gemini", 
    ".antigravity", ".antigravity-ide", ".antigravitycli", ".vscode", 
    ".npm", ".playwright-mcp", "AppData", "resilient-bardeen", "Downloads",
    "AntiProject", "spring", "scratch", "결번", "고용허가제참여기업리스트", "비즈노검수"
)

foreach ($f in $folders) {
    $p = "C:\Users\lg\$f"
    if (Test-Path $p) {
        $size = (Get-ChildItem -Path $p -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        $sizeGB = [math]::Round($size / 1GB, 2)
        if ($sizeGB -gt 0.05) {
            [PSCustomObject]@{ Folder = $f; SizeGB = $sizeGB }
        }
    }
}
